use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width = 0
    let mut ok = true
    let mut cur = ""
    let mut curlen = 0
    let mut lines: Vec<string> = []
    for line in text.lines() {
        if first {
            first = false
            let t = line.trim()
            match t.parse::<int>() {
                Ok(n) => {
                    if n > 0 && t.len() > 0 && !t.starts_with("+") {
                        width = n
                    } else {
                        ok = false
                    }
                }
                Err(_) => { ok = false }
            }
            if !ok {
                break
            }
        } else {
            for w in line.split_whitespace() {
                let wl: int = w.chars().count() as int
                if curlen == 0 {
                    cur = w
                    curlen = wl
                } else if curlen + 1 + wl <= width {
                    cur = "${cur} ${w}"
                    curlen = curlen + 1 + wl
                } else {
                    lines.push(cur)
                    cur = w
                    curlen = wl
                }
            }
        }
    }
    if !ok || first {
        println("error: bad width")
        std::process::exit(1)
    }
    if curlen > 0 {
        lines.push(cur)
    }
    for l in lines {
        println(l)
    }
}

